import sqlite3
import pandas as pd
import numpy as np
from datetime import datetime

# Connect to the SQLite database
conn = sqlite3.connect('dacomp-021.sqlite')

def perform_data_cleaning(conn, table_name, sample_size=10000):
    print(f"\n{'='*50}\nData Cleaning and Validation\n{'='*50}")

    try:
        # Get critical columns
        cursor = conn.cursor()
        cursor.execute(f"PRAGMA table_info({table_name})")
        columns = [col[1] for col in cursor.fetchall()]

        # Define cleaning columns
        cleaning_columns = {
            'ids': ['Booking ID', 'Customer ID'],
            'dates': ['Date'],
            'values': ['Booking Value', 'Ride Distance'],
            'categorical': ['Booking Status', 'Payment Method'],
            'text': ['Reason for cancelling by Customer']
        }

        # Filter to actual existing columns
        cleaning_columns = {k: [col for col in v if col in columns] for k, v in cleaning_columns.items()}

        # Get sample data with all needed columns
        select_cols = []
        for cols in cleaning_columns.values():
            for col in cols:
                if col in columns:
                    select_cols.append(f'"{col}"')

        if not select_cols:
            print("No valid columns found for cleaning")
            return None

        sample_query = f"""
        SELECT {', '.join(select_cols)}
        FROM "{table_name}"
        WHERE rowid IN (
            SELECT rowid FROM "{table_name}"
            ORDER BY RANDOM()
            LIMIT {sample_size}
        )
        """
        sample_data = pd.read_sql(sample_query, conn)

        # Data Cleaning Report
        print("\n1. Missing Value Imputation:")
        # Simple imputation for numeric columns
        for col in cleaning_columns['values']:
            if col in sample_data.columns:
                if sample_data[col].isnull().any():
                    # Impute with median for numeric columns
                    median_val = sample_data[col].median()
                    sample_data[col] = sample_data[col].fillna(median_val)
                    print(f"Imputed {sample_data[col].isnull().sum()} missing values in {col} with median {median_val}")

        # For categorical columns, use mode
        for col in cleaning_columns['categorical']:
            if col in sample_data.columns:
                if sample_data[col].isnull().any():
                    mode_val = sample_data[col].mode()[0]
                    sample_data[col] = sample_data[col].fillna(mode_val)
                    print(f"Imputed {sample_data[col].isnull().sum()} missing values in {col} with mode '{mode_val}'")

        # Date validation
        if 'Date' in sample_data.columns:
            print("\n2. Date Validation:")
            # Check date format consistency
            try:
                pd.to_datetime(sample_data['Date'], format='%Y/%m/%d')
                print("All dates in expected format YYYY/MM/DD")
            except Exception as e:
                print(f"Date format issues: {str(e)}")

        # Outlier detection
        print("\n3. Outlier Detection:")
        for col in cleaning_columns['values']:
            if col in sample_data.columns:
                q1 = sample_data[col].quantile(0.25)
                q3 = sample_data[col].quantile(0.75)
                iqr = q3 - q1
                lower_bound = q1 - 1.5 * iqr
                upper_bound = q3 + 1.5 * iqr
                outliers = sample_data[(sample_data[col] < lower_bound) | (sample_data[col] > upper_bound)]
                print(f"{col}: {len(outliers)} potential outliers (bounds: {lower_bound:.2f}-{upper_bound:.2f})")

        # Cancellation analysis
        if 'Booking Status' in sample_data.columns and 'Reason for cancelling by Customer' in sample_data.columns:
            print("\n4. Cancellation Analysis:")
            cancellation_reasons = sample_data.groupby('Booking Status')['Reason for cancelling by Customer'].value_counts().unstack()
            print(cancellation_reasons)

        return {
            'cleaned_data': sample_data,
            'cleaning_report': {
                'missing_values_imputed': {
                    col: sample_data[col].isnull().sum() for col in cleaning_columns['values'] + cleaning_columns['categorical']
                },
                'outliers_detected': {},
                'date_validation': 'Pass' if 'Date' in sample_data.columns else 'Not checked'
            }
        }

    except Exception as e:
        print(f"\nError during cleaning: {str(e)}")
        return None

# Perform data cleaning
results = perform_data_cleaning(conn, 'sheet1')

# Close connection
conn.close()

import sqlite3
import pandas as pd
import numpy as np
from datetime import datetime

# Connect to the SQLite database
conn = sqlite3.connect('dacomp-021.sqlite')

def generate_final_quality_report(conn, table_name, sample_size=10000):
    print(f"\n{'='*50}\nFinal Data Quality Report\n{'='*50}")

    try:
        # Get critical columns
        cursor = conn.cursor()
        cursor.execute(f"PRAGMA table_info({table_name})")
        columns = [col[1] for col in cursor.fetchall()]

        # Define analysis columns
        analysis_columns = {
            'ids': ['Booking ID', 'Customer ID'],
            'dates': ['Date'],
            'values': ['Booking Value', 'Ride Distance'],
            'categorical': ['Booking Status', 'Payment Method'],
            'text': ['Reason for cancelling by Customer']
        }

        # Filter to actual existing columns
        analysis_columns = {k: [col for col in v if col in columns] for k, v in analysis_columns.items()}

        # Get sample data with all needed columns
        select_cols = []
        for cols in analysis_columns.values():
            for col in cols:
                if col in columns:
                    select_cols.append(f'"{col}"')

        if not select_cols:
            print("No valid columns found for analysis")
            return None

        sample_query = f"""
        SELECT {', '.join(select_cols)}
        FROM "{table_name}"
        WHERE rowid IN (
            SELECT rowid FROM "{table_name}"
            ORDER BY RANDOM()
            LIMIT {sample_size}
        )
        """
        sample_data = pd.read_sql(sample_query, conn)

        # Generate Final Report
        report = {
            'summary': {},
            'detailed_analysis': {},
            'recommendations': []
        }

        # 1. Data Completeness
        print("\n1. Data Completeness:")
        missing_values = sample_data.isnull().sum()
        missing_pct = (missing_values / len(sample_data) * 100).round(2)
        report['summary']['missing_values'] = missing_values[missing_values > 0].to_dict()

        # 2. Data Quality Metrics
        print("\n2. Data Quality Metrics:")
        quality_metrics = {
            'missing_values': missing_values.sum(),
            'unique_values': {col: sample_data[col].nunique() for col in sample_data.columns},
            'data_types': {col: str(sample_data[col].dtype) for col in sample_data.columns}
        }
        report['summary']['quality_metrics'] = quality_metrics

        # 3. Detailed Analysis
        print("\n3. Detailed Analysis:")

        # Value Distributions
        value_distributions = {}
        for col in analysis_columns['values']:
            if col in sample_data.columns:
                desc = sample_data[col].describe()
                value_distributions[col] = {
                    'stats': desc.to_dict(),
                    'outliers': {
                        'lower_bound': desc['25%'] - 1.5*(desc['75%']-desc['25%']),
                        'upper_bound': desc['75%'] + 1.5*(desc['75%']-desc['25%']),
                        'outliers_count': sum((sample_data[col] < desc['25%'] - 1.5*(desc['75%']-desc['25%'])) | 
                                          (sample_data[col] > desc['75%'] + 1.5*(desc['75%']-desc['25%'])))
                    }
                }
        report['detailed_analysis']['value_distributions'] = value_distributions

        # Categorical Analysis
        categorical_analysis = {}
        for col in analysis_columns['categorical']:
            if col in sample_data.columns:
                categorical_analysis[col] = {
                    'value_counts': sample_data[col].value_counts().to_dict(),
                    'top_values': sample_data[col].value_counts().head(5).to_dict()
                }
        report['detailed_analysis']['categorical_analysis'] = categorical_analysis

        # Temporal Analysis
        if 'Date' in sample_data.columns:
            sample_data['Date'] = pd.to_datetime(sample_data['Date'])
            sample_data['Month'] = sample_data['Date'].dt.month
            monthly_counts = sample_data['Month'].value_counts().sort_index()
            report['detailed_analysis']['temporal_analysis'] = {
                'monthly_counts': monthly_counts.to_dict(),
                'trend': "No clear seasonality pattern"
            }

        # 4. Recommendations
        print("\n4. Recommendations:")
        recommendations = [
            "1. Implement data validation rules for booking values",
            "2. Standardize cancellation reason categories",
            "3. Investigate payment method anomalies",
            "4. Monitor temporal patterns for seasonality",
            "5. Implement data quality monitoring system"
        ]
        report['recommendations'] = recommendations

        # Prepare report for DataFrame conversion
        report_sections = {
            'summary': report['summary'],
            'detailed_analysis': report['detailed_analysis'],
            'recommendations': report['recommendations']
        }

        # Flatten report for DataFrame creation
        flat_data = []
        for section_name, section_data in report_sections.items():
            if isinstance(section_data, dict):
                for key, value in section_data.items():
                    flat_data.append({
                        'Section': section_name,
                        'Category': key,
                        'Value': str(value)
                    })
            else:
                flat_data.append({
                    'Section': section_name,
                    'Category': 'Overall',
                    'Value': str(section_data)
                })

        # Create DataFrame
        report_df = pd.DataFrame(flat_data)
        report_df.to_csv('data_quality_report.csv', index=False)
        print("\nSaved comprehensive report to 'data_quality_report.csv'")

        return report

    except Exception as e:
        print(f"\nError during final reporting: {str(e)}")
        return None

# Generate final report
final_report = generate_final_quality_report(conn, 'sheet1')

# Close connection
conn.close()
